                    formatter={(v, _n, p) => [
                      `${fmtPct(v)} (${p?.payload?.n})`,
                      "Reported",
                    ]}
                  />
                  <Bar dataKey="pct" fill="#eab308" radius={[0, 4, 4, 0]} />
