"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  PolarAngleAxis,
  PolarGrid,
  Radar,
  RadarChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  GLASS_PARTICIPATION,
  GLOBAL_BSI_COMBOS,
  HEADLINE,
  METRIC_OPTIONS,
  PEAK_CELLS,
  REGION_SHORT,
  REGIONAL_BSI,
  SOURCE_NOTE,
  TREND_ROWS,
  US_COMPARATOR,
  VIZ_MARKER,
  fmtPct,
  rankedRegionsBy,
  type MetricKey,
} from "@/data/who-glass-bloodstream-resistance-2026-data";

// viz-types: peak bars, region bars+radar, trend scatter+lines, US dual bars | controls: view + metric/filter

type ViewId = "peaks" | "regions" | "trends" | "us";
type FilterId = "all" | "lastline" | "firstchoice";

const COLORS = [
  "#0ea5e9",
  "#f97316",
  "#a855f7",
  "#22c55e",
  "#e11d48",
  "#eab308",
  "#64748b",
];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

