                  <XAxis
                    dataKey="name"
                    interval={0}
                    angle={-20}
                    textAnchor="end"
                    tick={{ fontSize: 10 }}
                    height={56}
                  />
                  <YAxis domain={[0, 80]} tickFormatter={(v) => `${v}%`} />
                  <Tooltip
                    formatter={(v) => [fmtPct(v, 0), "Approx share"]}
                  />
                  <Bar dataKey="pct" fill="#22c55e" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
