                    filter === "lastline"
                      ? /Imipenem/i.test(t.drug)
                      : filter === "firstchoice"
                        ? !/Imipenem/i.test(t.drug)
                        : true,
                  )}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" domain={[-15, 20]} unit="%" />
                  <YAxis
                    type="category"
                    dataKey="pathogen"
                    width={110}
                    tick={{ fontSize: 10 }}
                  />
                  <Tooltip
