                    textAnchor="end"
                    tick={{ fontSize: 10 }}
                    height={70}
                  />
                  <YAxis
                    domain={[0, 70]}
                    tickFormatter={(v) => `${v}%`}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v, _n, p) => [
                      `${fmtPct(Number(v))} (${p?.payload?.lo}???${p?.payload?.hi})`,
                      "Resistant",
                    ]}
                  />
                  <Bar dataKey="pct" fill="#0ea5e9" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "regions" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title={`Regional ranking ?? ${metricLabel}`}
            subtitle="WHO region bloodstream % (??? = last-line carbapenem)"
          >
            <div className="h-[340px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={regionBars}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 4, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 100]}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={48}
                    tick={{ fontSize: 12 }}
                  />
                  <Tooltip
                    formatter={(v) => [fmtPct(Number(v)), metricLabel]}
                    labelFormatter={(_, p) => p?.[0]?.payload?.region ?? ""}
                  />
                  <Bar dataKey="pct" fill="#f97316" radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Multi-metric radar ?? six regions"
