                  <Tooltip />
                </RadarChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-2 text-center text-xs text-slate-500">
              AFR ?? SEAR ?? EMR ?? EUR overlays ??? Americas / WPR omitted for
              readability
            </p>
          </ChartCard>
        </div>
      )}

      {view === "trends" && (
        <div className="grid gap-6 lg:grid-cols-2">
