                  <Tooltip
                    formatter={(v, _n, p) => [
                      `${fmtPct(Number(v))} (${p?.payload?.n})`,
                      "Reported",
                    ]}
                  />
                  <Bar dataKey="pct" fill="#eab308" radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}
